const d = msg.payload;
const g = id => d[`ns=2;s=Llenadora.${id}`];
const sts = {
    src: 'plc-llenado-01', online: true, fw_ver: 'sim-0.1.0',
    state_text: g('StateText'),
    auto_mode:  true,                 // Cmd.AutoMode se integra con el flujo cmd
    alarm_jam:  g('AlarmJam'),
    uptime_s:   g('UptimeS')
};
// comparar sin uptime_s (cambia siempre) para decidir si publicar
const cmp = JSON.stringify([sts.online, sts.state_text, sts.alarm_jam]);
if (cmp === context.get('cmp')) return null;
context.set('cmp', cmp);
return { topic: 'greytec/demo/produccion/llenado/plc-llenado-01/sts',
         qos: 1, retain: true,
         payload: { ts: new Date().toISOString(), ...sts } };

const d = msg.payload;
const state = d['ns=2;s=Llenadora.State'];
const text  = d['ns=2;s=Llenadora.StateText'];
const prev  = context.get('state');
context.set('state', state);
if (prev === undefined || prev === state) return null;

const ts   = new Date().toISOString();
const base = 'greytec/demo/produccion/llenado/plc-llenado-01/evt';
const out  = [{ topic: base, qos: 1, retain: false,
    payload: { ts, src: 'plc-llenado-01', evt_type: 'line_state_change',
               severity: 'info', msg: `Linea: ${prev} -> ${state} (${text})` } }];
if (state === 3) {
    out.push({ topic: base, qos: 1, retain: false,
        payload: { ts, src: 'plc-llenado-01', evt_type: 'jam_detected',
                   severity: 'alarm', msg: 'Atasco en la llenadora' } });
} else if (prev === 3) {
    out.push({ topic: base, qos: 1, retain: false,
        payload: { ts, src: 'plc-llenado-01', evt_type: 'jam_cleared',
                   severity: 'info', msg: 'Atasco despejado' } });
}
return [out];

const SRC = 'plc-llenado-01';
const DEADBAND = { line_state: 0, speed_bpm: 0.5, target_flow_kgh: 5,
                   valve_cmd_pct: 0.5, good_count: 0, bad_count: 0 }; 
const HEARTBEAT_MS = 30000;
const BASE = `greytec/demo/produccion/llenado/${SRC}/dat/raw`;

const last = context.get('last') || {};
let   seq  = context.get('seq')  || 0;   // seq POR DISPOSITIVO (§3.4)
const now  = Date.now();
const out  = [];

for (const [name, val] of Object.entries(msg.payload)) {
    const prev = last[name];
    const db = DEADBAND[name] ?? 0;
    const changed = prev === undefined
        || (typeof val.v === 'number' ? Math.abs(val.v - prev.v) > db
                                      : val.v !== prev.v)
        || val.q !== prev.q;
    if (changed || (now - prev.t) >= HEARTBEAT_MS) {
        seq += 1;
        last[name] = { v: val.v, q: val.q, t: now };
        out.push({ topic: `${BASE}/${name}`, qos: 1, retain: true,
                   payload: { ts: new Date().toISOString(), src: SRC, seq,
                              v: val.v, u: val.u, q: val.q } });
    }
}
context.set('last', last);
context.set('seq', seq);
return [out];

