function f32(r, i) {
    const b = Buffer.alloc(4);
    b.writeUInt16BE(r[i], 0);
    b.writeUInt16BE(r[i + 1], 2);
    return parseFloat(b.readFloatBE(0).toFixed(3));
}
const r  = msg.payload;
const st = r[16];
const plcOk = (st & 1) !== 0;
const air   = (st & 2) !== 0;
const qBase = plcOk ? 'good' : 'uncertain';
const qFlow = (plcOk && !air) ? 'good' : 'uncertain'; // dos fases → uncertain

msg.payload = {
    mass_flow_kgh:   { v: f32(r, 0), u: 'kg/h',  q: qFlow },
    volume_flow_lph: { v: f32(r, 2), u: 'L/h',   q: qBase },
    density_kgm3:    { v: f32(r, 4), u: 'kg/m³', q: qFlow },
    fluid_temp_c:    { v: f32(r, 6), u: '°C',    q: qBase },
    total_mass_kg:   { v: f32(r, 8), u: 'kg',    q: qBase }
};
msg.diag = {
    drive_gain_pct:  f32(r, 10),
    tube_freq_hz:    f32(r, 12),
    sensor_temp_c:   f32(r, 14),
    air_entrainment: air,
    plc_link_ok:     plcOk
};
return msg;

