const d = msg.diag;
const DB = { drive_gain_pct: 1, tube_freq_hz: 0.05, sensor_temp_c: 0.2 };
const prev = context.get('last');
const now = Date.now();
let publish = !prev || (now - prev.t) >= 60000
    || d.air_entrainment !== prev.d.air_entrainment
    || d.plc_link_ok     !== prev.d.plc_link_ok;
if (!publish) {
    for (const [k, db] of Object.entries(DB)) {
        if (Math.abs(d[k] - prev.d[k]) > db) { publish = true; break; }
    }
}
if (!publish) return null;
context.set('last', { d, t: now });
return { topic: 'greytec/demo/produccion/llenado/coriolis-01/diag',
         qos: 1, retain: false,
         payload: { ts: new Date().toISOString(), src: 'coriolis-01',
                    diag_type: 'transmitter_health', payload: d } };

function f32(r, i) {
    const b = Buffer.alloc(4);
    b.writeUInt16BE(r[i], 0);
    b.writeUInt16BE(r[i + 1], 2);
    return parseFloat(b.readFloatBE(0).toFixed(3));
}
const r = msg.payload;
const q = (r[12] & 1) ? 'good' : 'uncertain'; // sin PLC = consumo sin contexto

msg.payload = {
    voltage_v:      { v: f32(r, 0),  u: 'V',   q },
    current_a:      { v: f32(r, 2),  u: 'A',   q },
    active_power_w: { v: f32(r, 4),  u: 'W',   q },
    power_factor:   { v: f32(r, 6),  u: '',    q },
    frequency_hz:   { v: f32(r, 8),  u: 'Hz',  q },
    energy_kwh:     { v: f32(r, 10), u: 'kWh', q }
};
msg.plc_link_ok = (r[12] & 1) !== 0;
return msg;

